def _get_resource_info_from_arn(self, resource_arn: str) -> tuple:
    """Extract resource type and name from ARN, handling malformed ARNs."""
    try:
        # Handle empty ARN
        if not resource_arn:
            return "unknown", "unknown"

        # Try to extract resource type and name
        parts = resource_arn.split(":")
        if len(parts) < 6:
            return "unknown", "unknown"

        resource_part = parts[5]
        if "/" not in resource_part:
            return "unknown", "unknown"

        resource_type = resource_part.split("/")[0]
        resource_name = resource_arn.split("/")[-1]

        return resource_type, resource_name
    except Exception:
        # Fallback for any parsing errors
        return "unknown", "unknown"

